'use strict';
/* =========================================================================
 * MASQUE ROYALE ― 仮面領の一夜
 * データ駆動設計のカードゲーム本体。
 * カード1枚 = CARD_DEFS の1プロパティ。効果は effect 種別で分岐して処理する。
 * ========================================================================= */

/* ---------------------------------------------------------------------
 * 1. カードデータ定義
 * ------------------------------------------------------------------- */
const CARD_DEFS = {
  attendant:    { id:'attendant',    name:'給仕',         yomi:'きゅうじ',       number:1,  count:2, effect:'guessRank',
    desc:'相手の手札の数字を1つ宣言する。的中すれば相手は即座に脱落する（「1」は宣言できない）。', image:'data:image/jpeg;base64,' },
  musician:     { id:'musician',     name:'楽団員',       yomi:'がくだんいん',   number:2,  count:2, effect:'peekRange',
    desc:'楽団の調べで対象の仮面の"重み"を感じ取る。数字が「6以上」か「5以下」かだけを知る（正確な数字までは分からない）。', image:'data:image/jpeg;base64,' },
  fortune:      { id:'fortune',      name:'占い師',       yomi:'うらないし',     number:3,  count:2, effect:'peekDeckBottom',
    desc:'この夜の行く末を占う。山札の一番底――最後に引かれる仮面をこっそり覗き見る。', image:'data:image/jpeg;base64,' },
  noble_lady:   { id:'noble_lady',   name:'貴婦人',       yomi:'きふじん',       number:4,  count:2, effect:'protectSelf',
    desc:'次の自分の番が来るまで、他人の効果を受けない。', image:'data:image/jpeg;base64,' },
  spy:          { id:'spy',          name:'密偵',         yomi:'みってい',       number:5,  count:2, effect:'peekDeckTop',
    desc:'山札の一番上をこっそり確認し、そのまま戻すか山札の底へ送るか選べる。', image:'data:image/jpeg;base64,' },
  jester:       { id:'jester',       name:'道化師',       yomi:'どうけし',       number:6,  count:2, effect:'doubleRedraw',
    desc:'悪戯好きな道化師の仕業。自分と対象、双方の仮面を公開で捨てさせ、新しい仮面に総入れ替えする。', image:'data:image/jpeg;base64,' },
  taster:       { id:'taster',       name:'毒見役',       yomi:'どくみやく',     number:7,  count:2, effect:'secretRedraw',
    desc:'対象の仮面を、誰にも見せぬまま密かに毒杯へ沈めて処分し、山札から新しい1枚を引かせる。', image:'data:image/jpeg;base64,' },
  black_knight: { id:'black_knight', name:'黒騎士',       yomi:'くろきし',       number:8,  count:2, effect:'compareHand',
    desc:'対象と手札の数字をこっそり比べ合い、低い方が脱落する（同数なら何も起きない）。', image:'data:image/jpeg;base64,' },
  grand_duke:   { id:'grand_duke',   name:'大公',         yomi:'たいこう',       number:9,  count:1, effect:'foreseeTwo',
    desc:'静かなる策略家。自分だけの慧眼で山札の次の2枚を見通し、望むなら並びを入れ替える（対象は取らない）。',
    image:'data:image/jpeg;base64,' },
  masked_host:  { id:'masked_host',  name:'仮面の主催者', yomi:'かめんのしゅさいしゃ', number:10, count:1, effect:'none',
    desc:'自分の番にこの仮面を自ら場に出すと、その場で正体が露見し即座に脱落する。ただし他者の効果で捨てさせられた場合や、勝敗を決める最後の公開時にはこの効果は発動しない（MASCARADEの黄金律）。最強にして最も脆い切り札。',
    exposeEliminates:true, image:'data:image/jpeg;base64,' },
};
const CARD_ORDER = ['attendant','musician','fortune','noble_lady','spy','jester','taster','black_knight','grand_duke','masked_host'];

/* ---------------------------------------------------------------------
 * 2. ユーティリティ
 * ------------------------------------------------------------------- */
function shuffle(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}
function buildFreshDeck(){
  const deck = [];
  CARD_ORDER.forEach(id=>{
    const def = CARD_DEFS[id];
    for(let i=0;i<def.count;i++) deck.push(id);
  });
  return shuffle(deck);
}
function cardDef(id){ return CARD_DEFS[id]; }
function uniq(){ return Math.random().toString(36).slice(2,9); }
// 演出用のCPU「間」。ヘッドレステスト（__TEST_FORCE_CPU）実行時のみ短縮する。
function pace(ms){ return (typeof window!=='undefined' && window.__TEST_FORCE_CPU) ? Math.min(10, ms) : ms; }
// CPUの思考待ち時間。難易度ごとの倍率をかけた上でpace()に通す。
function cpuPace(ms){
  const diff = (typeof Game!=='undefined' && Game.difficulty && DIFFICULTY_DEFS[Game.difficulty]) ? DIFFICULTY_DEFS[Game.difficulty] : DIFFICULTY_DEFS.courtier;
  return pace(ms * diff.speedMul);
}

/* ---------------------------------------------------------------------
 * 2b. 難易度定義
 * ------------------------------------------------------------------- */
const DIFFICULTY_DEFS = {
  novice:   { id:'novice',   label:'新米仮面卿',   epithet:'駆け引きに不慣れで、隙が多い。',           speedMul:1.3 },
  courtier: { id:'courtier', label:'仮面卿',       epithet:'標準的な駆け引きをこなす、舞踏会の顔。',     speedMul:1.0 },
  wily:     { id:'wily',     label:'老獪な仮面卿', epithet:'記憶力と読みに長け、手強い相手。',           speedMul:0.78 },
};
const DIFFICULTY_ORDER = ['novice','courtier','wily'];

/* ---------------------------------------------------------------------
 * 2c. 戦績（連勝）の永続化
 * ------------------------------------------------------------------- */
const STATS_KEY = 'mascarade_stats_v1';
function loadStats(){
  try{
    if(typeof localStorage==='undefined') return {};
    const raw = localStorage.getItem(STATS_KEY);
    return raw ? JSON.parse(raw) : {};
  }catch(e){ return {}; }
}
function saveStats(stats){
  try{
    if(typeof localStorage!=='undefined') localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }catch(e){ /* プライベートモード等で失敗しても致命的ではないので握りつぶす */ }
}
function ensureDiffStats(stats, diffId){
  if(!stats[diffId]) stats[diffId] = { wins:0, losses:0, draws:0, streak:0, best:0, played:0 };
  return stats[diffId];
}

/* ---------------------------------------------------------------------
 * 3. ゲーム状態 & コアロジック
 * ------------------------------------------------------------------- */
const Game = {
  state: null,
  difficulty: 'courtier',
  stats: loadStats(),

  setDifficulty(id){
    if(DIFFICULTY_DEFS[id]) this.difficulty = id;
  },

  newGame(){
    const deck = buildFreshDeck();
    const removedCard = deck.pop(); // 転生札（誰にも見えない1枚、裏向きで除外）
    const forceCPU = (typeof window!=='undefined' && window.__TEST_FORCE_CPU); // ヘッドレステスト専用フック
    const diff = DIFFICULTY_DEFS[this.difficulty] || DIFFICULTY_DEFS.courtier;
    CPU.rangeMemory = {}; // 前の対戦の記憶を持ち越さない
    CPU.bottomMemory = null;
    const players = [
      { id:0, name:'あなた', isCPU: !!forceCPU, hand:[deck.pop()], alive:true, protectedFlag:false, discard:[] },
      { id:1, name:diff.label, isCPU:true,  hand:[deck.pop()], alive:true, protectedFlag:false, discard:[] },
    ];
    this.state = {
      deck, removedCard,
      players,
      turnIndex: Math.random()<0.5 ? 0 : 1,
      turnCount: 0,
      log: [],
      phase: 'idle',       // idle | choose | resolve | over
      pendingCard: null,   // 選択済みだが未解決のカードID（対象/数字待ち）
      gameOver: false,
      winner: null,
      endReason: null,
    };
    UI.showTable();
    this.addLog(`舞踏会の幕が上がる。1枚の仮面が「転生札」として裏向きに除外された。最初の番は「${players[this.state.turnIndex].name}」。`, true);
    UI.render();
    this.startTurn();
  },

  addLog(text, isTurnHeader){
    this.state.log.push({ text, header: !!isTurnHeader });
  },

  me(){ return this.state.players[0]; },
  opp(){ return this.state.players[1]; },
  other(idx){ return idx===0?1:0; },
  playerAt(idx){ return this.state.players[idx]; },

  startTurn(){
    const s = this.state;
    if(!s || s.gameOver) return;
    s.turnCount++;
    const p = s.players[s.turnIndex];

    // 山札が尽きた場合はここでゲーム終了（比べ合い）
    if(s.deck.length===0){
      this.endGameByShowdown();
      return;
    }

    p.protectedFlag = false; // 加護は自分の番が来た時点で解除
    const drawn = s.deck.pop();
    p.hand.push(drawn);
    this.addLog(`── ${p.name} の番（${s.turnCount}巡）──`, true);
    this.addLog(`${p.name} は山札から仮面を1枚引いた。`);
    if(typeof UI!=='undefined' && UI.showTurnBanner){ UI.showTurnBanner(`${p.name}の番`); }

    s.phase = 'choose';
    UI.render();

    if(p.isCPU){
      setTimeout(()=>CPU.takeTurn(), cpuPace(1500));
    }
  },

  /* 手札からカードを1枚選んで場に出す（プレイする） */
  discardCard(playerIdx, cardId, opts){
    opts = opts || {};
    const s = this.state;
    if(!s) return;
    const p = s.players[playerIdx];
    const idx = p.hand.indexOf(cardId);
    if(idx===-1){ console.error('hand mismatch', playerIdx, cardId, p.hand); return; }
    p.hand.splice(idx,1);
    p.discard.push(cardId);
    const def = cardDef(cardId);

    if(!opts.forced){
      this.addLog(`${p.name} は「${def.name}（${def.number}）」の仮面を外し、場に出した。`);
    } else {
      this.addLog(`${p.name} は掟に従い「${def.name}（${def.number}）」を場に出した。`);
    }

    // 仮面の主催者は捨てられた瞬間に脱落
    if(def.exposeEliminates){
      this.eliminate(playerIdx, `「${def.name}」を自ら場に出してしまい、正体が露見した`);
      UI.render();
      if(this.checkGameEnd()) return;
      this.advanceTurn();
      return;
    }

    if(opts.forced || def.effect==='none'){
      // 効果を持たないカード（大公など）。このカードを出したことが今回の番の行動そのものであり、
      // これでターンは終了する（もう1枚は次の自分の番まで手札に残る）。
      UI.render();
      if(this.checkGameEnd()) return;
      this.advanceTurn();
      return;
    }

    // 効果解決フェーズへ
    s.phase = 'resolve';
    s.pendingCard = cardId;
    UI.render();
  },

  /* 有効な対象（生存していて、加護されていない相手）を1体返す（2人対戦なので常に相手固定） */
  validOpponentIdx(actorIdx){
    const t = this.other(actorIdx);
    const tp = this.playerAt(t);
    if(!tp.alive) return null;
    if(tp.protectedFlag) return null;
    return t;
  },

  /* ---------------- 各効果の解決 ---------------- */

  effGuessRank(actorIdx, guessNumber){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.addLog(`${actor.name} は「給仕」を使ったが、${target.protectedFlag?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
      this.finishResolve();
      return;
    }
    const targetCard = target.hand[0];
    const hit = cardDef(targetCard).number === guessNumber;
    this.addLog(`${actor.name}は「${target.name}の手札は${guessNumber}」と宣言した…${hit?'的中！':'外れ。'}`);

    const resultHtml = hit
      ? `${actor.name}は${target.name}の手札を「${guessNumber}」と見抜いた！<br><br>${UI.cardInline(targetCard)}<br><br><b style="color:var(--gold-light)">${target.name}は正体を見破られ、退場する。</b>`
      : `${actor.name}は${target.name}の手札を「${guessNumber}」と宣言したが、<b>外れた</b>。<br>${target.name}の正体はまだ分からない。`;

    const applyResult = () => {
      if(hit){ this.eliminate(t, `${actor.name}の宣言が的中し、正体が見破られた`); }
      this.finishResolve();
    };
    UI.showInfoModal('給仕の宣言', resultHtml, applyResult, true);
  },

  // 楽団員：対象の手札が「高い(6-10)」か「低い(1-5)」かだけを知る（数字までは分からない部分情報）
  effPeekRange(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.addLog(`${actor.name} は「楽団員」を使ったが、${target.protectedFlag?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
      this.finishResolve();
      return;
    }
    const tCard = target.hand[0];
    const num = cardDef(tCard).number;
    const isHigh = num >= 6;
    this.addLog(`${actor.name}は楽団の調べで${target.name}の仮面の"重み"を感じ取った。（${isHigh?'重い（6以上）':'軽い（5以下）'}）`);
    if(!actor.isCPU){
      UI.showInfoModal('楽団員の調べ', `${target.name}の仮面は…<br><br><b style="font-size:20px; color:var(--gold-light);">${isHigh?'重い（数字は6以上）':'軽い（数字は5以下）'}</b>`, ()=>{
        this.finishResolve();
      }, true);
    } else {
      CPU.rangeMemory[t] = isHigh; // CPUは大まかな重みを記憶する
      this.finishResolve();
    }
  },

  // 占い師：山札の一番底（＝この夜、最後に引かれる仮面）を覗き見る
  effPeekDeckBottom(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    if(s.deck.length===0){
      this.addLog(`${actor.name}は「占い師」に山札の行く末を占わせたが、山札は空だった。`);
      this.finishResolve();
      return;
    }
    const bottom = s.deck[0];
    this.addLog(`${actor.name}は占い師に、この夜の行く末（山札の底）を占わせた。`);
    if(!actor.isCPU){
      UI.showInfoModal('占い師の予見', `この夜、最後に引かれる仮面は…<br><br>${UI.cardInline(bottom)}`, ()=>{
        this.finishResolve();
      }, true);
    } else {
      CPU.bottomMemory = bottom; // CPUは最後の1枚を記憶する
      this.finishResolve();
    }
  },

  effProtectSelf(actorIdx){
    const actor = this.playerAt(actorIdx);
    actor.protectedFlag = true;
    this.addLog(`${actor.name}は「貴婦人」の加護を得た。次の自分の番までは狙われない。`);
    this.finishResolve();
  },

  effPeekDeckTop(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    if(s.deck.length===0){
      this.addLog(`${actor.name}は「密偵」を使ったが、山札は残っていなかった。`);
      this.finishResolve();
      return;
    }
    const top = s.deck[s.deck.length-1];
    this.addLog(`${actor.name}は山札の一番上をこっそり確認した。`);
    if(!actor.isCPU){
      UI.showInfoModal('密偵の報告', `山札の一番上は…<br><br>${UI.cardInline(top)}<br><br>このまま戻すか、山札の底へ送るか選んでください。`,
        null, true, [
          {label:'そのまま戻す', action:()=>{ this.addLog(`${actor.name}は山札をそのままにした。`); this.finishResolve(); }},
          {label:'底へ送る', action:()=>{ s.deck.pop(); s.deck.unshift(top); this.addLog(`${actor.name}は見た仮面を山札の底へ送った。`); this.finishResolve(); }},
        ]);
    } else {
      // CPUの選択（老獪な仮面卿は次に引くのが相手であることを踏まえて判断する）
      const topNum = cardDef(top).number;
      let sendToBottom;
      if(Game.difficulty==='wily'){
        sendToBottom = topNum >= 6; // 価値の高い仮面は相手に渡さない
      } else {
        sendToBottom = Math.random() < 0.5;
      }
      if(sendToBottom){ s.deck.pop(); s.deck.unshift(top); this.addLog(`${actor.name}は見た仮面を山札の底へ送ったようだ。`); }
      else { this.addLog(`${actor.name}は山札をそのままにしたようだ。`); }
      this.finishResolve();
    }
  },

  // 道化師：自分と対象、双方の手札を「公開でその場に捨てさせ」新しい仮面に総入れ替えする悪戯
  effDoubleRedraw(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.addLog(`${actor.name} は「道化師」を使ったが、${target.protectedFlag?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
      this.finishResolve();
      return;
    }
    // 入れ替え用の仮面が両者分（2枚）確保できない場合は空手札を作らないよう、そもそも発動させない
    const available = s.deck.length + (s.removedCard ? 1 : 0);
    if(available < 2){
      this.addLog(`${actor.name}は「道化師」で悪戯しようとしたが、入れ替える仮面が山札に十分残っていなかった。`);
      this.finishResolve();
      return;
    }
    // MASCARADEの黄金律：他者の効果で捨てさせられた場合、その仮面自体の効果は発動しない
    const drawOne = (p) => {
      const oldCard = p.hand.pop();
      p.discard.push(oldCard);
      let newCard = null;
      if(s.deck.length>0){ newCard = s.deck.pop(); }
      else if(s.removedCard){ newCard = s.removedCard; s.removedCard = null; }
      if(newCard) p.hand.push(newCard);
      return oldCard;
    };
    const targetOld = drawOne(target);
    const actorOld = drawOne(actor);
    this.addLog(`${actor.name}は道化師の悪戯で、${target.name}と自分、双方の仮面を総入れ替えした。（${target.name}が手放したのは${cardDef(targetOld).name}、${actor.name}が手放したのは${cardDef(actorOld).name}）`);
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`🃏 ${actor.name}と${target.name}、双方の仮面が入れ替わった`, 'info'); }
    this.finishResolve();
  },

  // 毒見役：対象の仮面を誰にも見せぬまま密かに処分し、新しい仮面を引かせる
  effSecretRedraw(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.addLog(`${actor.name} は「毒見役」を使ったが、${target.protectedFlag?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
      this.finishResolve();
      return;
    }
    // 代わりの仮面が1枚も確保できない場合は、対象の手札を空にしないよう発動させない
    const available = s.deck.length + (s.removedCard ? 1 : 0);
    if(available < 1){
      this.addLog(`${actor.name}は「毒見役」を使おうとしたが、代わりの仮面が山札に残っていなかった。`);
      this.finishResolve();
      return;
    }
    // MASCARADEの黄金律：他者の効果で処分された場合、その仮面自体の効果は発動しない。しかも今回は誰にも公開されない。
    const oldCard = target.hand.pop(); // あえて discard には加えない＝正体を明かさず密かに処分
    this.addLog(`${actor.name}は${target.name}の仮面を、誰にも見せぬまま密かに毒杯へ沈めた。`);
    let newCard = null;
    if(s.deck.length>0){ newCard = s.deck.pop(); }
    else if(s.removedCard){ newCard = s.removedCard; s.removedCard = null; this.addLog('山札が尽きていたため、転生札が使われた。'); }
    target.hand.push(newCard);
    this.addLog(`${target.name}は山札から新しい仮面を引いた。`);
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`🍷 ${target.name}の仮面が、誰にも知られぬまま処分された`, 'info'); }
    this.finishResolve();
  },

  effCompareHand(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.addLog(`${actor.name} は「黒騎士」を使ったが、${target.protectedFlag?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
      this.finishResolve();
      return;
    }
    const aCard = actor.hand[0], tCard = target.hand[0];
    const aDef = cardDef(aCard), tDef = cardDef(tCard);
    this.addLog(`${actor.name}と${target.name}は仮面の数字を見せ合った。（${actor.name}:${aDef.name} / ${target.name}:${tDef.name}）`);

    // MASCARADEの黄金律：比べ合いによる公開だけでは脱落しない。数字の大小のみで決着する
    let loserIdx = null, outcomeText;
    if(aDef.number < tDef.number){ loserIdx = actorIdx; outcomeText = `<b style="color:var(--gold-light)">${target.name}の勝ち。</b>${actor.name}は数字で及ばず、正体が露見する。`; }
    else if(tDef.number < aDef.number){ loserIdx = t; outcomeText = `<b style="color:var(--gold-light)">${actor.name}の勝ち。</b>${target.name}は数字で及ばず、正体が露見する。`; }
    else { outcomeText = '数字は同じ。両者、決着つかず。'; }

    const applyResult = () => {
      if(loserIdx!==null){
        this.eliminate(loserIdx, loserIdx===actorIdx ? `${target.name}との対決に敗れた` : `${actor.name}との対決に敗れた`);
      } else {
        this.addLog('数字は同じだった。両者、決着つかず。');
      }
      this.finishResolve();
    };
    const modalHtml = `${actor.name}: ${UI.cardInline(aCard)}<br><br>${target.name}: ${UI.cardInline(tCard)}<br><br>${outcomeText}`;
    if(actor.isCPU && target.isCPU){
      applyResult();
    } else {
      UI.showInfoModal('黒騎士の対決', modalHtml, applyResult, true);
    }
  },

  // 大公：自分の目で山札の次の2枚を見通し、望むなら並びを入れ替える（自分専用の慧眼、対象を取らない）
  effForeseeTwo(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    if(s.deck.length===0){
      this.addLog(`${actor.name}は「大公」の力で山札の行方を占おうとしたが、山札は空だった。`);
      this.finishResolve();
      return;
    }
    if(s.deck.length===1){
      const only = s.deck[s.deck.length-1];
      this.addLog(`${actor.name}は山札を占ったが、残るは1枚だけだった。`);
      if(!actor.isCPU){
        UI.showInfoModal('大公の慧眼', `山札に残る最後の仮面は…<br><br>${UI.cardInline(only)}`, ()=>this.finishResolve(), true);
      } else {
        this.finishResolve();
      }
      return;
    }
    const topIdx = s.deck.length-1;
    const secondIdx = s.deck.length-2;
    const top = s.deck[topIdx];       // 次に引かれる1枚
    const second = s.deck[secondIdx]; // その次に引かれる1枚
    this.addLog(`${actor.name}は「大公」の慧眼で、山札の行方を占った。`);
    const doSwap = () => { const tmp=s.deck[topIdx]; s.deck[topIdx]=s.deck[secondIdx]; s.deck[secondIdx]=tmp; };
    if(!actor.isCPU){
      UI.showInfoModal('大公の慧眼', `次に引かれる仮面は…<br><br>${UI.cardInline(top)}<br><br>その次に引かれる仮面は…<br><br>${UI.cardInline(second)}<br><br>並びを入れ替えますか？`, null, true, [
        {label:'入れ替える', action:()=>{ doSwap(); this.addLog(`${actor.name}は山札の並びを入れ替えた。`); this.finishResolve(); }},
        {label:'そのままにする', action:()=>{ this.addLog(`${actor.name}は山札をそのままにした。`); this.finishResolve(); }},
      ]);
    } else {
      let doIt = false;
      if(Game.difficulty==='wily'){
        doIt = cardDef(top).number > cardDef(second).number; // 強い方を相手に渡したくない
      } else if(Game.difficulty==='courtier'){
        doIt = Math.random() < 0.5;
      }
      if(doIt){ doSwap(); this.addLog(`${actor.name}は山札の並びを入れ替えたようだ。`); }
      else { this.addLog(`${actor.name}は山札をそのままにしたようだ。`); }
      this.finishResolve();
    }
  },

  finishResolve(){
    const s = this.state;
    if(!s) return;
    s.pendingCard = null;
    s.phase = 'idle';
    UI.render();
    if(this.checkGameEnd()) return;
    this.advanceTurn();
  },

  eliminate(playerIdx, reason){
    const s = this.state;
    const p = s.players[playerIdx];
    if(!p.alive) return;
    p.alive = false;
    // 残った手札は公開して捨て札へ
    while(p.hand.length){
      const c = p.hand.pop();
      p.discard.push(c);
    }
    this.addLog(`💀 ${p.name} は退場した。（${reason}）`);
    if(typeof UI!=='undefined' && UI.flashEliminated){ UI.flashEliminated(playerIdx); }
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`💀 ${p.name}が退場（${reason}）`, 'danger', 2600); }
  },

  checkGameEnd(){
    const s = this.state;
    const alive = s.players.filter(p=>p.alive);
    if(alive.length<=1){
      s.gameOver = true;
      s.winner = alive[0] || null;
      s.endReason = 'elimination';
      s.phase = 'over';
      this.recordResult();
      UI.render();
      UI.showGameOver();
      return true;
    }
    return false;
  },

  endGameByShowdown(){
    const s = this.state;
    const alive = s.players.filter(p=>p.alive);
    let winner = null;
    if(alive.length===1){ winner = alive[0]; }
    else if(alive.length>1){
      let best = -1;
      alive.forEach(p=>{
        // 万一手札が空のプレイヤーがいても（想定外の経路で起きても）クラッシュしないよう防御しておく
        const n = p.hand[0] ? cardDef(p.hand[0]).number : -1;
        if(n>best){ best=n; winner=p; }
        else if(n===best){ winner=null; } // 同数タイは引き分け扱い
      });
    }
    s.gameOver = true;
    s.winner = winner;
    s.endReason = 'showdown';
    s.phase = 'over';
    this.recordResult();
    this.addLog('山札が尽きた。仮面を開き、最後の見比べが行われる。');
    UI.render();
    UI.showGameOver();
  },

  // 現在選択中の難易度に対する戦績（勝敗・連勝）を更新して保存する
  recordResult(){
    const s = this.state;
    const st = ensureDiffStats(this.stats, this.difficulty);
    st.played++;
    if(s.winner && s.winner.id===0){
      st.wins++; st.streak++; st.best = Math.max(st.best, st.streak);
    } else if(s.winner && s.winner.id===1){
      st.losses++; st.streak = 0;
    } else {
      st.draws++; st.streak = 0;
    }
    saveStats(this.stats);
  },

  advanceTurn(){
    const s = this.state;
    if(!s || s.gameOver) return;
    s.turnIndex = this.other(s.turnIndex);
    s.phase = 'idle';
    const nextIsCPU = s.players[s.turnIndex].isCPU;
    setTimeout(()=>this.startTurn(), nextIsCPU ? cpuPace(900) : pace(350));
  },
};

/* ---------------------------------------------------------------------
 * 4. 簡易CPU AI
 * ------------------------------------------------------------------- */
const CPU = {
  memory: {},       // { playerIdx: cardId } 占い師(旧)などで知った正確な情報の名残（現在は未使用の予備領域）
  rangeMemory: {},  // { playerIdx: boolean } 楽団員で知った「重い/軽い」の大まかな情報
  bottomMemory: null, // 占い師で見た「山札の底（最後の1枚）」の記憶

  takeTurn(){
    const s = Game.state;
    if(!s) return;
    const idx = s.turnIndex;
    const p = s.players[idx];
    if(!p.isCPU || s.phase!=='choose') return;

    const diffId = Game.difficulty || 'courtier';
    const hand = p.hand.slice();
    let chosen;
    // 「仮面の主催者」は絶対に自分からは出さない（もう1枚がある限り）
    if(hand.includes('masked_host') && hand.length===2){
      chosen = hand.find(c=>c!=='masked_host');
    } else if(diffId==='novice'){
      // 新米：ほとんど考えずランダムに選ぶ
      chosen = hand[Math.floor(Math.random()*hand.length)];
    } else {
      const t = Game.other(idx);
      const scored = hand.map((c,i)=>{
        const d = cardDef(c);
        const n = d.number;
        const otherCard = hand[1-i];
        let score = (10-n) + Math.random() * (diffId==='wily' ? 2 : 4);
        if(diffId==='wily' && otherCard){
          // 老獪：もう1枚の状況を踏まえて有利な効果を優先する
          const otherNum = cardDef(otherCard).number;
          if(d.effect==='guessRank' && CPU.rangeMemory[t]!==undefined) score += 4;
          if(d.effect==='compareHand'){
            if(otherNum>=6) score += 4;
            else if(otherNum<=3) score -= 3;
          }
          if(d.effect==='protectSelf' && (otherCard==='grand_duke' || otherCard==='masked_host')) score += 4;
        }
        return { c, score };
      });
      scored.sort((a,b)=>b.score-a.score);
      chosen = scored[0].c;
    }

    Game.discardCard(idx, chosen);

    // discardCard は効果を持たないカード（大公など）や「仮面の主催者」露見の場合、
    // 自分でターンを終わらせる。ここでは効果解決待ち(resolveフェーズ)の場合のみ担当する。
    setTimeout(()=>{
      if(!Game.state || Game.state.gameOver) return;
      if(Game.state.pendingCard === chosen && Game.state.phase==='resolve'){
        this.resolvePending(idx, chosen);
      }
    }, cpuPace(1100));
  },

  guessWeightedNumber(actorIdx){
    const s = Game.state;
    const diffId = Game.difficulty || 'courtier';
    if(diffId==='novice'){
      // 新米：情報を活かさずほぼランダムに宣言する
      return 2 + Math.floor(Math.random()*9);
    }
    const remaining = {}; // number -> 残数
    CARD_ORDER.forEach(id=>{
      const d = cardDef(id);
      if(d.number===1) return; // 1は宣言不可
      remaining[d.number] = d.count;
    });
    // 見えている札（捨て札全部、自分の手札）を減算
    const seen = [];
    s.players.forEach(pl=>seen.push(...pl.discard));
    seen.push(...s.players[actorIdx].hand);
    seen.forEach(cid=>{
      const n = cardDef(cid).number;
      if(remaining[n]!==undefined) remaining[n] = Math.max(0, remaining[n]-1);
    });
    // 楽団員で知った「重い/軽い」の大まかな記憶があれば、その範囲内から絞り込む
    const t = Game.other(actorIdx);
    let pool = [];
    Object.keys(remaining).forEach(n=>{
      for(let i=0;i<remaining[n];i++) pool.push(Number(n));
    });
    if(CPU.rangeMemory[t] !== undefined){
      const isHigh = CPU.rangeMemory[t];
      const narrowed = pool.filter(n => isHigh ? n>=6 : n<=5);
      if(narrowed.length>0) pool = narrowed;
    }
    if(pool.length===0) return 2 + Math.floor(Math.random()*9);
    return pool[Math.floor(Math.random()*pool.length)];
  },

  resolvePending(actorIdx, cardId){
    const def = cardDef(cardId);
    switch(def.effect){
      case 'guessRank': Game.effGuessRank(actorIdx, this.guessWeightedNumber(actorIdx)); break;
      case 'peekRange': Game.effPeekRange(actorIdx); break;
      case 'peekDeckBottom': Game.effPeekDeckBottom(actorIdx); break;
      case 'protectSelf': Game.effProtectSelf(actorIdx); break;
      case 'peekDeckTop': Game.effPeekDeckTop(actorIdx); break;
      case 'doubleRedraw': Game.effDoubleRedraw(actorIdx); break;
      case 'secretRedraw': Game.effSecretRedraw(actorIdx); break;
      case 'compareHand': Game.effCompareHand(actorIdx); break;
      case 'foreseeTwo': Game.effForeseeTwo(actorIdx); break;
      default: Game.finishResolve();
    }
  },
};

/* ---------------------------------------------------------------------
 * 5. UI 描画
 * ------------------------------------------------------------------- */
const UI = {
  selectedCardId: null,

  init(){
    this.buildRulesPanel();
    this.buildSparkles();
    this.buildCandleGlow();
    this.bindRippleEffect();
    this.buildDifficultyPicker();
    this.buildStartDeco();
    this.initSplash();
  },

  // タイトル画面下部の余白を彩る、装飾用の仮面カード（大公・貴婦人）
  buildStartDeco(){
    const el = document.getElementById('start-deco');
    if(!el) return;
    const picks = ['grand_duke', 'noble_lady'];
    el.innerHTML = picks.map((id, i)=>{
      const d = cardDef(id);
      return `<div class="deco-card ${i===0?'a':'b'}"><img src="${d.image}" alt="${d.name}" loading="lazy"></div>`;
    }).join('');
  },

  initSplash(){
    this.buildSplashParticles();
    this.buildSplashTitle();
    const fill = document.getElementById('splash-progress-fill');
    const progressBar = document.getElementById('splash-progress');
    const sub = document.getElementById('splash-sub');
    const btn = document.getElementById('splash-start-btn');
    const reveal = () => {
      if(progressBar) progressBar.style.display = 'none';
      if(sub) sub.style.display = 'none';
      if(btn) btn.classList.add('show');
    };
    if(this.reducedMotion()){ reveal(); return; }

    // 読み込みバーを0→100%まで滑らかに進める
    if(fill){
      const raf = (typeof window!=='undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn)=>setTimeout(fn, 16);
      raf(()=>{ fill.style.width = '100%'; });
    }

    // ローディング中、雰囲気のある一言を数百ms間隔で切り替える
    const captions = ['仮面領の扉を開いています…', '燭台に灯をともしています…', '仮面を選んでいます…'];
    let idx = 0;
    const captionTimer = setInterval(()=>{
      idx = (idx+1) % captions.length;
      if(sub){ sub.style.opacity = '0'; setTimeout(()=>{ if(sub) { sub.textContent = captions[idx]; sub.style.opacity = '1'; } }, 200); }
    }, 500);

    setTimeout(()=>{ clearInterval(captionTimer); reveal(); }, 1600);
  },

  buildSplashTitle(){
    const el = document.getElementById('splash-title');
    if(!el) return;
    const text = 'MASCARADE';
    const reduced = this.reducedMotion();
    el.innerHTML = text.split('').map((ch,i)=>
      `<span style="${reduced?'':`animation-delay:${(i*0.06).toFixed(2)}s`}">${ch}</span>`
    ).join('');
  },

  buildSplashParticles(){
    const layer = document.getElementById('splash-particles');
    if(!layer) return;
    let html = '';
    for(let i=0;i<18;i++){
      const top = Math.random()*100, left = Math.random()*100, delay = Math.random()*6;
      html += `<div class="sparkle" style="top:${top}%; left:${left}%; animation-delay:${delay}s;"></div>`;
    }
    layer.innerHTML = html;
  },

  dismissSplash(){
    const el = document.getElementById('splash-screen');
    if(el) el.classList.add('dismissed');
  },

  buildDifficultyPicker(){
    const row = document.getElementById('difficulty-row');
    const epithetEl = document.getElementById('difficulty-epithet');
    if(!row) return;
    row.innerHTML = DIFFICULTY_ORDER.map(id=>{
      const d = DIFFICULTY_DEFS[id];
      return `<button class="diff-btn${id===Game.difficulty?' active':''}" data-diff="${id}" onclick="UI.selectDifficulty('${id}')">${d.label}</button>`;
    }).join('');
    if(epithetEl) epithetEl.textContent = DIFFICULTY_DEFS[Game.difficulty].epithet;
    this.renderStatsPanel();
  },

  selectDifficulty(id){
    Game.setDifficulty(id);
    document.querySelectorAll('.diff-btn').forEach(b=>b.classList.toggle('active', b.dataset.diff===id));
    const epithetEl = document.getElementById('difficulty-epithet');
    if(epithetEl) epithetEl.textContent = DIFFICULTY_DEFS[id].epithet;
    this.renderStatsPanel();
  },

  renderStatsPanel(){
    const el = document.getElementById('stats-panel');
    if(!el) return;
    const st = Game.stats[Game.difficulty];
    if(!st || st.played===0){
      el.innerHTML = `<span class="stats-empty">この相手とはまだ対戦していません</span>`;
      return;
    }
    const streakHtml = st.streak>0
      ? `<span class="stats-streak">${st.streak}連勝中</span>`
      : `<span class="stats-streak off">連勝なし</span>`;
    el.innerHTML = `
      <span class="stats-record">${st.wins}勝 ${st.losses}敗 ${st.draws}分</span>
      ${streakHtml}
      <span class="stats-best">自己ベスト ${st.best}連勝</span>
    `;
  },

  buildCandleGlow(){
    const layer = document.getElementById('sparkle-layer');
    if(!layer) return;
    ['a','b','c'].forEach(cls=>{
      const div = document.createElement('div');
      div.className = `candle-glow ${cls}`;
      layer.appendChild(div);
    });
  },

  bindRippleEffect(){
    document.addEventListener('click', (e)=>{
      const btn = e.target.closest('.btn, .btn-grand');
      if(!btn || this.reducedMotion()) return;
      const rect = btn.getBoundingClientRect();
      const ripple = document.createElement('span');
      ripple.className = 'ripple';
      ripple.style.left = (e.clientX - rect.left) + 'px';
      ripple.style.top = (e.clientY - rect.top) + 'px';
      btn.appendChild(ripple);
      setTimeout(()=>ripple.remove(), 650);
    });
  },

  buildSparkles(){
    const layer = document.getElementById('sparkle-layer');
    if(!layer) return;
    let html='';
    for(let i=0;i<26;i++){
      const top = Math.random()*100, left = Math.random()*100, delay = Math.random()*6;
      html += `<div class="sparkle" style="top:${top}%; left:${left}%; animation-delay:${delay}s;"></div>`;
    }
    layer.innerHTML = html;
  },

  rulesHtml(){
    let rows = '';
    CARD_ORDER.forEach(id=>{
      const d = cardDef(id);
      rows += `<div class="rule-card-row">
        <div class="rule-thumb"><img src="${d.image}" alt="${d.name}" loading="lazy"></div>
        <div class="rule-text">
          <span class="rn">${d.number}. ${d.name}</span><span class="ry">（${d.yomi}）</span>
          <div class="rd">${d.desc}</div>
        </div>
        <div class="rule-count">×${d.count}</div>
      </div>`;
    });
    return `${rows}
      <div class="rd" style="margin:14px 0 6px; opacity:.85;">
        数字が小さいほど「攻めの読み合い」向き。数字が大きいほど希少で、抱え続ける価値と危険の両方を持つ切り札です。
      </div>
      <div class="rd" style="margin:10px 0 6px; opacity:.85;">
        <b style="color:var(--gold-light);">MASCARADEの黄金律</b>：カードの効果が発動するのは、自分の番に自分でその仮面を場に出した時のみ。他人の効果で捨てさせられた場合や、山札切れによる最後の公開では、効果は発動しません。
      </div>
      <div class="rd" style="margin:10px 0 6px; opacity:.85;">
        カードの情報を探るため、対戦相手への簡単な質問も自由です。より高度な心理戦をお楽しみください。
      </div>`;
  },

  buildRulesPanel(){
    const panel = document.getElementById('rules-panel');
    if(!panel) return;
    panel.innerHTML = `<h3>仮面一覧（全18枚）</h3>${this.rulesHtml()}`;
  },

  showHelpModal(){
    const overlay = document.getElementById('help-overlay');
    const box = document.getElementById('help-box');
    if(!overlay || !box) return;
    box.innerHTML = `
      <button class="help-close" onclick="UI.closeHelpModal()" aria-label="閉じる">×</button>
      <h3>仮面一覧とルール</h3>
      ${this.rulesHtml()}
    `;
    overlay.classList.add('open');
  },

  closeHelpModal(){
    const overlay = document.getElementById('help-overlay');
    if(overlay) overlay.classList.remove('open');
  },

  toggleRules(){
    const panel = document.getElementById('rules-panel');
    const btn = document.getElementById('rules-toggle-btn');
    const open = panel.classList.toggle('open');
    btn.textContent = (open?'▴':'▾') + ' 仮面の一覧とルールを見る';
  },

  toggleLog(){
    const panel = document.getElementById('log-panel');
    const open = panel.classList.toggle('open');
    if(open) this.renderLog();
  },

  showTable(){
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('table').classList.add('open');
    document.body.classList.add('table-mode');
    const header = document.getElementById('site-header');
    if(header) header.classList.add('compact');
  },

  backToStart(){
    const s = Game.state;
    if(s && !s.gameOver){
      const ok = window.confirm('対戦中です。タイトルへ戻ると今の勝負は終了します。よろしいですか？');
      if(!ok) return;
    }
    document.getElementById('info-overlay').classList.remove('open');
    document.getElementById('gameover-overlay').classList.remove('open');
    document.getElementById('discard-overlay').classList.remove('open');
    document.getElementById('log-panel').classList.remove('open');
    document.getElementById('table').classList.remove('open');
    document.getElementById('start-screen').style.display = '';
    document.body.classList.remove('table-mode');
    const header = document.getElementById('site-header');
    if(header) header.classList.remove('compact');
    Game.state = null;
  },

  cardInline(cid){
    const d = cardDef(cid);
    return `<span style="display:inline-flex;align-items:center;gap:8px;vertical-align:middle;">
      <img class="card-inline-img" src="${d.image}" alt="${d.name}" style="width:34px;aspect-ratio:300/505;object-fit:cover;border-radius:5px;box-shadow:0 2px 6px rgba(0,0,0,0.5);">
      <b>${d.name}（${d.number}）</b>
    </span>`;
  },

  render(){
    if(!Game.state) return;
    const s = Game.state;
    const me = Game.me(), opp = Game.opp();

    document.getElementById('turn-badge').textContent =
      s.gameOver ? '舞踏会、終幕' : `${s.players[s.turnIndex].name}の番`;
    document.getElementById('deck-count-text').textContent = `山札 ${s.deck.length}枚`;

    // 相手
    document.getElementById('opp-name').textContent = opp.name;
    document.getElementById('opp-protect').classList.toggle('show', opp.protectedFlag);
    document.getElementById('opp-eliminated').classList.toggle('show', !opp.alive);
    const oppThinking = !s.gameOver && s.turnIndex===1 && (s.phase==='choose' || s.phase==='resolve');
    document.getElementById('opp-hand').innerHTML = opp.hand.map(()=>
      `<div class="card-back${oppThinking?' thinking':''}"><span class="mask-icon">🎭</span></div>`).join('');

    // 自分
    document.getElementById('me-protect').classList.toggle('show', me.protectedFlag);
    document.getElementById('me-eliminated').classList.toggle('show', !me.alive);
    const meCanChoose = !s.gameOver && s.phase==='choose' && s.turnIndex===0;
    if(!meCanChoose) this.selectedCardId = null; // 自分の選択フェーズ以外では選択状態を破棄
    document.getElementById('me-hand').innerHTML = me.hand.map((cid,i)=>this.renderCard(cid,{
      selectable: meCanChoose,
      chosen: cid===this.selectedCardId,
      onclick: `UI.onMeSelectCard('${cid}')`,
    })).join('');

    this.renderActionPanel();
    if(document.getElementById('log-panel').classList.contains('open')) this.renderLog();
    if(document.getElementById('discard-overlay').classList.contains('open')) this.showDiscardModal();
  },

  renderCard(cid, opts){
    opts = opts || {};
    const d = cardDef(cid);
    const cls = ['card'];
    if(opts.selectable) cls.push('selectable');
    if(opts.chosen) cls.push('chosen');
    return `<div class="${cls.join(' ')}" data-cid="${cid}" ${opts.selectable?`onclick="${opts.onclick}"`:''} title="${d.name}（${d.number}）">
      <img src="${d.image}" alt="${d.name}（${d.number}）">
    </div>`;
  },

  renderDiscardChips(discardArr){
    if(!discardArr.length) return `<span class="chip empty" style="opacity:.5;">まだ何も出ていない</span>`;
    return discardArr.map(cid=>{
      const d = cardDef(cid);
      return `<span class="chip ${d.exposeEliminates?'host':''}" title="${d.name}（${d.number}）">
        <img src="${d.image}" alt="${d.name}">
        <b>${d.number}</b> ${d.name}
      </span>`;
    }).join('');
  },

  showDiscardModal(){
    const overlay = document.getElementById('discard-overlay');
    const box = document.getElementById('discard-box');
    if(!overlay || !box) return;
    const s = Game.state;
    if(!s) return;
    const me = Game.me(), opp = Game.opp();
    box.innerHTML = `
      <button class="help-close" onclick="UI.closeDiscardModal()" aria-label="閉じる">×</button>
      <h3>これまでに場に出された仮面</h3>
      <div class="discard-modal-section">
        <h5>${me.name}</h5>
        <div class="discard-strip">${this.renderDiscardChips(me.discard)}</div>
      </div>
      <div class="discard-modal-section">
        <h5>${opp.name}</h5>
        <div class="discard-strip">${this.renderDiscardChips(opp.discard)}</div>
      </div>
    `;
    overlay.classList.add('open');
  },

  closeDiscardModal(){
    const overlay = document.getElementById('discard-overlay');
    if(overlay) overlay.classList.remove('open');
  },

  renderLog(){
    const panel = document.getElementById('log-panel');
    const s = Game.state;
    if(!s) return;
    const lines = s.log.map(l=> l.header ? `<div class="lg-turn">${l.text}</div>` : `<div>${l.text}</div>`).join('');
    panel.innerHTML = `<button class="lg-close" onclick="UI.toggleLog()" aria-label="閉じる"></button>${lines}`;
    panel.scrollTop = panel.scrollHeight;
  },

  renderActionPanel(){
    const s = Game.state;
    const box = document.getElementById('ap-prompt');
    const panel = document.getElementById('action-panel');

    if(s.gameOver){
      box.innerHTML = '結果は下の画面をご覧ください。';
      panel.querySelectorAll('.choice-row, .num-pad, .sub').forEach(n=>n.remove());
      return;
    }

    // 既存の動的要素を除去してから作り直す
    panel.querySelectorAll('.choice-row, .num-pad, .sub, .card').forEach(n=>n.remove());

    if(s.phase==='resolve' && s.pendingCard){
      const cid = s.pendingCard;
      const d = cardDef(cid);
      const actorIsMe = s.turnIndex===0;
      if(!actorIsMe){
        box.innerHTML = `${Game.opp().name}が「${d.name}」の力を発動している…`;
        return;
      }
      if(d.effect==='guessRank'){
        box.innerHTML = `「${d.name}」発動：${Game.opp().name}の手札の数字を宣言してください（1は宣言できません）`;
        const pad = document.createElement('div');
        pad.className = 'num-pad';
        for(let n=2;n<=10;n++){
          const b = document.createElement('button');
          b.className='btn'; b.textContent=n;
          b.onclick = ()=>Game.effGuessRank(0, n);
          pad.appendChild(b);
        }
        panel.appendChild(pad);
        return;
      }
      // 自分専用の情報効果は、自動的に発動して結果モーダルを開く（確認クリックを挟まない）
      if(d.effect==='peekDeckTop'){
        box.innerHTML = `「${d.name}」発動中…`;
        Game.effPeekDeckTop(0);
        return;
      }
      if(d.effect==='peekDeckBottom'){
        box.innerHTML = `「${d.name}」発動中…`;
        Game.effPeekDeckBottom(0);
        return;
      }
      if(d.effect==='foreseeTwo'){
        box.innerHTML = `「${d.name}」発動中…`;
        Game.effForeseeTwo(0);
        return;
      }
      if(d.effect==='protectSelf'){
        box.innerHTML = `「${d.name}」の加護を求めます。`;
        const row = document.createElement('div');
        row.className='choice-row';
        const b = document.createElement('button');
        b.className='btn primary'; b.textContent='発動する';
        b.onclick = ()=>Game.effProtectSelf(0);
        row.appendChild(b);
        panel.appendChild(row);
        return;
      }
      if(['peekRange','doubleRedraw','secretRedraw','compareHand'].includes(d.effect)){
        box.innerHTML = `「${d.name}」の力を${Game.opp().name}に対して発動します。`;
        const row = document.createElement('div');
        row.className='choice-row';
        const b = document.createElement('button');
        b.className='btn primary'; b.textContent='発動する';
        b.onclick = ()=>{
          if(d.effect==='peekRange') Game.effPeekRange(0);
          else if(d.effect==='doubleRedraw') Game.effDoubleRedraw(0);
          else if(d.effect==='secretRedraw') Game.effSecretRedraw(0);
          else if(d.effect==='compareHand') Game.effCompareHand(0);
        };
        row.appendChild(b);
        panel.appendChild(row);
        return;
      }
    }

    if(s.phase==='choose'){
      if(s.turnIndex===0){
        if(this.selectedCardId){
          const d = cardDef(this.selectedCardId);
          box.innerHTML = `「${d.name}（${d.number}）」を場に出しますか？<br><span class="sub-desc">${d.desc}</span>`;
          const row = document.createElement('div');
          row.className = 'choice-row';
          const okBtn = document.createElement('button');
          okBtn.className = 'btn primary'; okBtn.textContent = 'この仮面を場に出す';
          okBtn.onclick = () => this.confirmPlaySelected();
          const cancelBtn = document.createElement('button');
          cancelBtn.className = 'btn ghost'; cancelBtn.textContent = 'やめる';
          cancelBtn.onclick = () => this.cancelSelection();
          row.appendChild(okBtn); row.appendChild(cancelBtn);
          panel.appendChild(row);
        } else {
          box.innerHTML = 'どちらの仮面を場に出しますか？（手札から1枚を選んでください）';
        }
      } else {
        box.innerHTML = `${Game.opp().name}が思案している…`;
      }
      return;
    }

    box.innerHTML = '―';
  },

  onMeSelectCard(cid){
    const s = Game.state;
    if(!s || s.phase!=='choose' || s.turnIndex!==0) return;
    this.selectedCardId = (this.selectedCardId===cid) ? null : cid;
    this.render();
  },

  cancelSelection(){
    this.selectedCardId = null;
    this.render();
  },

  confirmPlaySelected(){
    const cid = this.selectedCardId;
    if(!cid) return;
    const s = Game.state;
    if(!s || s.phase!=='choose' || s.turnIndex!==0) return;
    this.selectedCardId = null;
    const el = document.querySelector(`#me-hand .card[data-cid="${cid}"]`);
    if(el && !this.reducedMotion()){
      // 選択不可にして二重クリックを防ぐ
      document.querySelectorAll('#me-hand .card.selectable').forEach(c=>{ c.classList.remove('selectable'); c.onclick=null; });
      this.flyCardToDiscard(el, 'fab-discard');
      setTimeout(()=>Game.discardCard(0, cid), 380);
    } else {
      Game.discardCard(0, cid);
    }
  },

  reducedMotion(){
    return typeof window!=='undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  },

  flyCardToDiscard(el, targetId){
    const rect = el.getBoundingClientRect();
    const targetEl = document.getElementById(targetId);
    if(!targetEl){ return; }
    const trect = targetEl.getBoundingClientRect();
    const clone = el.cloneNode(true);
    clone.classList.add('flying-card');
    clone.classList.remove('selectable');
    clone.style.left = rect.left+'px';
    clone.style.top = rect.top+'px';
    clone.style.width = rect.width+'px';
    clone.style.height = rect.height+'px';
    clone.style.margin = '0';
    document.body.appendChild(clone);
    el.style.visibility = 'hidden';

    const raf = (typeof window!=='undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn)=>setTimeout(fn, 16);
    raf(()=>{
      const dx = (trect.left + Math.min(trect.width,40)/2) - (rect.left + rect.width/2);
      const dy = (trect.top + trect.height/2) - (rect.top + rect.height/2);
      clone.style.transform = `translate(${dx}px, ${dy}px) rotate(340deg) scale(0.45)`;
      clone.style.opacity = '0.2';
    });
    setTimeout(()=>{ clone.remove(); }, 520);
  },

  showTurnBanner(text){
    if(this.reducedMotion()) return;
    const el = document.createElement('div');
    el.className = 'turn-banner';
    el.textContent = text;
    document.body.appendChild(el);
    setTimeout(()=>el.remove(), 1750);
  },

  showToast(text, kind, duration){
    kind = kind || 'info';
    duration = duration || 2200;
    const el = document.createElement('div');
    el.className = `turn-banner toast ${kind}`;
    el.textContent = text;
    document.body.appendChild(el);
    if(this.reducedMotion()){
      el.style.animation = 'none';
      el.style.opacity = '1';
      el.style.transform = 'translate(-50%,0)';
    }
    setTimeout(()=>el.remove(), duration);
  },

  flashEliminated(playerIdx){
    const zoneId = playerIdx===0 ? 'player-zone' : 'opponent-zone';
    const zone = document.getElementById(zoneId);
    if(!zone) return;
    zone.classList.remove('elim-flash');
    void zone.offsetWidth; // reflow でアニメーションを再トリガー
    zone.classList.add('elim-flash');
    setTimeout(()=>zone.classList.remove('elim-flash'), 750);
  },

  spawnBurstParticles(container, palette){
    if(this.reducedMotion() || !container) return;
    const colors = palette || ['var(--gold-light)','var(--gold)','var(--royal)'];
    for(let i=0;i<26;i++){
      const p = document.createElement('span');
      p.className = 'burst-particle';
      const angle = Math.random()*Math.PI*2;
      const dist = 60 + Math.random()*120;
      p.style.setProperty('--tx', `${Math.cos(angle)*dist}px`);
      p.style.setProperty('--ty', `${Math.sin(angle)*dist}px`);
      p.style.background = colors[Math.floor(Math.random()*colors.length)];
      p.style.animationDelay = `${Math.random()*0.15}s`;
      container.appendChild(p);
      setTimeout(()=>p.remove(), 1300);
    }
  },

  showInfoModal(title, html, onClose, showCloseBtn, customButtons){
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    let btnHtml = '';
    if(customButtons){
      btnHtml = `<div class="choice-row">${customButtons.map((b,i)=>`<button class="btn ${i===0?'primary':''}" data-cb="${i}">${b.label}</button>`).join('')}</div>`;
    } else if(showCloseBtn){
      btnHtml = `<div class="choice-row"><button class="btn primary" id="info-ok-btn">わかった</button></div>`;
    }
    box.innerHTML = `<h4>${title}</h4><p>${html}</p>${btnHtml}`;
    overlay.classList.add('open');
    if(customButtons){
      customButtons.forEach((b,i)=>{
        box.querySelector(`[data-cb="${i}"]`).onclick = ()=>{
          overlay.classList.remove('open');
          b.action();
        };
      });
    } else {
      const okBtn = document.getElementById('info-ok-btn');
      if(okBtn){
        okBtn.onclick = ()=>{ overlay.classList.remove('open'); if(onClose) onClose(); };
      } else if(onClose){
        // ボタンが無い呼び出しのフォールバック：オーバーレイを確実に閉じてから続行する
        overlay.classList.remove('open');
        onClose();
      }
    }
  },

  showGameOver(){
    const s = Game.state;
    const overlay = document.getElementById('gameover-overlay');
    const box = document.getElementById('gameover-box');
    let title, sub, palette;
    if(s.winner && s.winner.id===0){ title='あなたの勝利'; sub='正体を隠し通し、王位を継承した。'; palette=['var(--gold-light)','var(--gold)','var(--royal)']; }
    else if(s.winner && s.winner.id===1){ title=`${s.players[1].name}の勝利`; sub='あなたの正体は見破られてしまった。'; palette=['var(--velvet-light)','var(--danger)','var(--gold-dim)']; }
    else { title='引き分け'; sub='舞踏会は決着つかず幕を閉じた。'; palette=['var(--silver)','var(--ivory-dim)','var(--gold-dim)']; }

    const revealRow = s.players.map(p=>{
      const cid = p.hand[0];
      return `<div class="reveal-row" style="display:flex;justify-content:space-between;align-items:center;font-size:12.5px;padding:6px 0;border-top:1px dashed rgba(255,255,255,0.1);">
        <span>${p.name}</span><span>${cid ? UI.cardInline(cid) : (p.alive?'—':'退場')}</span>
      </div>`;
    }).join('');

    const st = Game.stats[Game.difficulty] || { streak:0, best:0, wins:0, losses:0, draws:0 };
    let streakLine;
    if(s.winner && s.winner.id===0 && st.streak>0){
      streakLine = `<div class="result-streak win">${st.streak}連勝中！（自己ベスト ${st.best}連勝）</div>`;
    } else if(s.winner && s.winner.id===1){
      streakLine = st.best>0
        ? `<div class="result-streak lose">連勝はここで途切れた（自己ベスト ${st.best}連勝）</div>`
        : '';
    } else {
      streakLine = '';
    }
    const recordLine = `<div class="result-record">通算 ${st.wins}勝 ${st.losses}敗 ${st.draws}分</div>`;

    box.innerHTML = `
      <div class="result-title">${title}</div>
      <div class="result-sub">${sub}</div>
      ${streakLine}
      ${revealRow}
      ${recordLine}
      <div class="start-actions" style="margin-top:18px;">
        <button class="btn-grand" onclick="UI.restart()">もう一度舞踏会へ</button>
      </div>
    `;
    overlay.classList.add('open');
    this.spawnBurstParticles(box, palette);
  },

  restart(){
    document.getElementById('gameover-overlay').classList.remove('open');
    Game.newGame();
  },
};

document.addEventListener('DOMContentLoaded', ()=>UI.init());

/* PWA: Service Worker登録（オフライン対応・ホーム画面への追加）
   新しいバージョンが有効化されたら、開いたままのタブも自動で1回だけ再読み込みして最新化する。
   （GitHubへpush→デプロイ後、アプリを開き直すだけでアイコンやインストール状態はそのままに中身だけ更新される） */
if('serviceWorker' in navigator){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('./sw.js').then(()=>{
      let refreshed = false;
      navigator.serviceWorker.addEventListener('controllerchange', ()=>{
        if(refreshed) return;
        refreshed = true;
        window.location.reload();
      });
    }).catch((err)=>{
      console.warn('Service Worker の登録に失敗しました', err);
    });
  });
}

/* テスト用フック（jsdomヘッドレステストから利用。通常のプレイには使用しない） */
if(typeof window!=='undefined'){
  window.__masqueTestHooks = { Game, CPU, UI, CARD_DEFS, DIFFICULTY_DEFS };
}
